<script setup>defineProps({metrics:{type:Array,default:()=>[]},title:{type:String,default:'Advanced metrics'},source:{type:String,default:''}})</script>
<template><section class="advanced-table"><header><div><span class="eyebrow">ADVANCED PROFILE</span><h2>{{title}}</h2></div><small>{{source}}</small></header><div class="table" v-if="metrics.length"><article v-for="metric in metrics" :key="metric.key||metric.label" :title="metric.definition"><span>{{metric.label}}<i>?</i></span><b>{{metric.value}}</b><em v-if="metric.percentile!=null">P{{metric.percentile}}</em><small>{{metric.definition}}</small></article></div><p v-else>Advanced source fields are unavailable for this player.</p></section></template>
<style scoped>.advanced-table{border:1px solid var(--line);background:var(--surface)}header{padding:18px 20px;display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid var(--line)}h2{margin:5px 0 0;font-size:27px}header>small{max-width:260px;text-align:right;font:600 7px/1.4 'DM Mono';color:var(--muted)}.table{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line)}article{min-height:155px;padding:15px;display:flex;flex-direction:column;background:var(--surface)}article>span{font-size:9px;font-weight:800}article>span i{display:inline-grid;place-items:center;width:14px;height:14px;margin-left:5px;border:1px solid var(--line);border-radius:50%;font:700 7px 'DM Mono';font-style:normal;color:var(--muted)}article b{margin:auto 0 4px;font:800 25px 'DM Mono'}article em{font:800 8px 'DM Mono';font-style:normal;color:var(--sport,var(--accent))}article small{min-height:27px;margin-top:7px;font-size:6px;line-height:1.45;color:var(--muted)}.advanced-table>p{padding:30px;color:var(--muted);font-size:9px}@media(max-width:900px){.table{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.table{grid-template-columns:1fr}}</style>
